import { inject, Injectable, signal } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { BehaviorSubject, Observable, single, Subject } from 'rxjs';
import { NotificationsService } from 'src/app/_services/notifications.service';
import { ApiService } from 'src/app/_services/api.service';

import {
    Categories,
    Category,
    Units,
} from 'src/app/core/interfaces/stock.interface';
import { Products } from 'src/app/core/interfaces/stock.interface';
import { ExchangeRate } from '../core/interfaces/rates.interface';
import * as moment from 'moment';
import { DateService } from '../_services/date.service';

@Injectable({
    providedIn: 'root',
})
export class StockService {
    readonly dateService = inject(DateService);
    constructor(
        private http: HttpClient,
        private notificationService: NotificationsService,
        private api: ApiService
    ) {
        this.getExchangeRate();
        this.getCategories();
        this.getItems();
        this.getUnitsOfMeasure();
        this.getRecentRates();
        this.getDeliveryCharge();
        // this.getRatesGraph(this.graphYear.value)
    }

    public resetSellPage() {
        this.selectedCategorySell.next({
            category_name: 'No Category Selected!',
        });
        this.sellFilteredItems.next([]);
    }

    private host = this.api.host;
    public exchangeRate = new BehaviorSubject({});
    recentRates = new BehaviorSubject<ExchangeRate[]>([]);
    graphRates = new BehaviorSubject([]);
    graphYear = new BehaviorSubject(moment().year().toString());

    public units = new BehaviorSubject<Units[]>([]);

    public categories = new BehaviorSubject<Categories[]>([]);
    categoryDialogVisible = new BehaviorSubject<boolean>(false);
    public selectedCategory = new BehaviorSubject(0);
    public items = new BehaviorSubject([]);
    public filteredItems = new BehaviorSubject([]);
    public selectedItem = new BehaviorSubject(0);
    public totalStock = new BehaviorSubject({
        totalCost: 0,
        totalPrice: 0,
    });
    rateDialogVisible = new BehaviorSubject<boolean>(false);

    // sell model
    public selectedCategorySell = new BehaviorSubject({
        category_name: 'No Category Selected!',
    });
    public sellFilteredItems = new BehaviorSubject([]);

    itemDialogVisible = new BehaviorSubject<boolean>(false);
    stockDialogVisible = new BehaviorSubject<boolean>(false);

    barcodeError = new Subject<void>();

    // #################################### Units ###############################################

    // get units of measure
    getUnitsOfMeasure() {
        this.http.get<Units[]>(`${this.host}/stock/units`).subscribe({
            next: (res: Units[]) => {
                this.units.next(res);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'categories');
            },
        });
    }

    // #################################### Categories ###############################################
    // ##########################################################################################

    // get all categories
    getCategories() {
        this.http.get<Categories[]>(`${this.host}/stock/categories`).subscribe({
            next: (res) => {
                this.categories.next(res);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'categories');
            },
        });
    }

    // category row selection
    selectCategory(category) {
        this.selectedCategory.next(category);
        this.selectedItem.next(0);
    }

    // add new category
    createCategory(data) {
        this.http.post(`${this.host}/stock/categories`, data).subscribe({
            next: (res: Categories) => {
                let values = this.categories.value;
                values.push(res);
                this.categories.next(values);
                this.notificationService.showSuccess(
                    'Category has been added successfully!',
                    'home'
                );
                this.categoryDialogVisible.next(false);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    // reorder categories
    sortCategories() {
        this.http
            .patch<Categories[]>(
                `${this.host}/stock/categories/sort`,
                this.categories.value
            )
            .subscribe({
                next: (res) => {
                    this.categories.next(res);
                    this.notificationService.showSuccess(
                        'Rows reordered successfully!',
                        'home'
                    );
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // update category
    updateCategory(category) {
        this.http
            .put<any>(`${this.host}/stock/categories`, category)
            .subscribe({
                next: (res) => {
                    this.notificationService.showSuccess(res.message, 'home');
                    this.getCategories();
                    // this.resetSellPage();
                    this.categoryDialogVisible.next(false);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // delete category
    deleteCategory(category) {
        this.http
            .delete<any>(
                `${this.host}/stock/categories/${category.category_id}`
            )
            .subscribe({
                next: (res) => {
                    this.notificationService.showSuccess(res.message, 'home');
                    this.getCategories();
                    this.selectedCategory.next(0);
                    this.resetSellPage();
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // #################################### Items ###############################################
    // ##########################################################################################

    itemsLoading = signal(false);
    getItems() {
        this.itemsLoading.set(true);
        this.http.get<Products[]>(`${this.host}/stock/items`).subscribe({
            next: (res) => {
                this.items.next(res);
                this.itemsLoading.set(false);
            },
            error: (error: HttpErrorResponse) => {
                this.itemsLoading.set(false);
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    getFilteredItems(category, location: string) {
        this.http
            .get<Products[]>(`${this.host}/stock/items/${category.category_id}`)
            .subscribe({
                next: (res) => {
                    if (location == 'stock') {
                        this.filteredItems.next(res);
                    } else {
                        this.sellFilteredItems.next(res);
                    }
                    this.itemsLoading.set(false);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                    this.itemsLoading.set(false);
                },
            });
    }

    // category row selection
    selectItem(item) {
        this.selectedItem.next(item);
    }

    // add item
    createItem(item) {
        this.http.post(`${this.host}/stock/items`, item).subscribe({
            next: (res) => {
                let values = this.items.value;
                values.push(res);
                this.items.next(values);
                this.getFilteredItems(this.selectedCategory.value, 'stock');
                this.notificationService.showSuccess(
                    'Item Created Successfully!',
                    'home'
                );
                this.resetSellPage();
            },
            error: (error: HttpErrorResponse) => {
                if (error.status == 400) {
                    this.barcodeError.next();
                }
                this.notificationService.handleError(error, 'home');
            },
            complete: () => {
                this.itemDialogVisible.next(false);
            },
        });
    }

    // update item
    updateItem(item) {
        this.http.put<any>(`${this.host}/stock/items`, item).subscribe({
            next: (res) => {
                this.notificationService.showSuccess(res.message, 'home');
                this.getItems();
                this.getFilteredItems(this.selectedCategory.value, 'stock');
                this.resetSellPage();
            },
            error: (error: HttpErrorResponse) => {
                if (error.status == 400) {
                    this.barcodeError.next();
                }
                this.notificationService.handleError(error, 'home');
            },
            complete: () => {
                this.itemDialogVisible.next(false);
            },
        });
    }

    // delete item
    deleteItem(product) {
        this.http
            .delete<any>(`${this.host}/stock/items/${product.product_id}`)
            .subscribe({
                next: (res) => {
                    this.notificationService.showSuccess(res.message, 'home');
                    this.getItems();
                    this.getFilteredItems(this.selectedCategory.value, 'stock');
                    this.selectedItem.next(0);
                    this.resetSellPage();
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // $$$$$$$$$$$$$$$$$$$$$$$$$$$$$$ Exchange Rate $$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

    // get exchange rate
    getExchangeRate() {
        this.http.get(`${this.host}/stock/rate`).subscribe({
            next: (res: any) => {
                this.exchangeRate.next(res);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    // update exchange rate
    updateExchangeRate(rate) {
        this.http.post<any>(`${this.host}/stock/rate`, rate).subscribe({
            next: (res) => {
                this.notificationService.showSuccess(
                    'Rate updated successfully!',
                    'home'
                );
                this.exchangeRate.next(res);
                this.rateDialogVisible.next(false);
                this.getRecentRates();
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    // get recent rates
    getRecentRates() {
        this.http.get<ExchangeRate[]>(`${this.host}/stock/rates`).subscribe({
            next: (res: ExchangeRate[]) => {
                this.recentRates.next(res);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    // get rates for graph
    getRatesGraph(year) {
        this.http.get<any>(`${this.host}/stock/rates/graph/${year}`).subscribe({
            next: (res) => {
                // console.log(res);
                this.graphRates.next(res);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    // ************************** STOCK CORRECTION ***********************************
    submitStock(data) {
        this.http.post<any>(`${this.host}/stock/correction`, data).subscribe({
            next: (res) => {
                // let values = this.items.value;
                // values.push(res);
                // this.items.next(values);
                // this.getFilteredItems(this.selectedCategory.value, 'stock');
                // this.notificationService.showSuccess(
                //     'Stock Updated Successfully!',
                //     'home'
                // );
                this.notificationService.showSuccess(res.message, 'home');
                this.getItems();
                this.getFilteredItems(this.selectedCategory.value, 'stock');
                this.resetSellPage();
                this.stockDialogVisible.next(false);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    // **************************** Fetch Stock History *********************************

    stockHistory = signal([]);
    historyLoading = signal(false);
    historyDialogVisible = signal(false);

    fetchStockHistory(id: number) {
        this.historyLoading.set(true);
        this.http.get(`${this.host}/stock/history/${id}`).subscribe({
            next: (res: any) => {
                this.historyLoading.set(false);
                this.stockHistory.set(res);
                this.historyDialogVisible.set(true);
            },
            error: (error: HttpErrorResponse) => {
                this.historyLoading.set(false);
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    // @@@@@@@@@@@@@@@@@@@@@@@@@@@ Stock Archive @@@@@@@@@@@@@@@@@@@@@@@@@@@

    archiveLoading = signal(false);
    productArchive = signal([]);

    startDate = signal(this.dateService.getStartOfCurrentMonth());
    endDate = signal(this.dateService.getCurrentDate());

    fetchArchive() {
        let start = this.dateService.formatDate(this.startDate());
        let end = this.dateService.formatDate(this.endDate());

        this.archiveLoading.set(true);
        this.http
            .get(`${this.api.host}/stock/items/${start}&${end}`)
            .subscribe({
                next: (res: any) => {
                    this.archiveLoading.set(false);
                    this.productArchive.set(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.showError(error.error, 'home');
                    this.archiveLoading.set(false);
                },
            });
    }

    // fix average cost
    avgCostLoading = signal(false);
    fixAverageCost() {
        this.avgCostLoading.set(true);
        this.http.get(`${this.api.host}/stock/average-cost`).subscribe({
            next: (res: any) => {
                this.getItems();
                this.notificationService.showSuccess(res.message, 'home');
                this.avgCostLoading.set(false);
            },
            error: (error: HttpErrorResponse) => {
                console.log(error.message);
                this.notificationService.showError(error.message, 'home');
                this.avgCostLoading.set(false);
            },
        });
    }

    // delivery charge methods
    deliveryChargeValue = signal(null);
    deliveryChargeDialogVisible = signal(false);
    getDeliveryCharge() {
        this.http.get(`${this.host}/stock/settings`).subscribe({
            next: (res: any) => {
                this.deliveryChargeValue.set(res.setting_value);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.showError(error.error, 'home');
            },
        });
    }

    updateDeliveryLoading = signal(false);
    // update deliveryCharge
    updateDeliveryCharge(value: number) {
        this.updateDeliveryLoading.set(true);
        this.http.put(`${this.host}/stock/settings`, value).subscribe({
            next: (res: any) => {
                this.deliveryChargeValue.set(res.setting_value);
                this.deliveryChargeDialogVisible.set(false);
                this.notificationService.showSuccess(
                    'Delivery Charge Updated Successfully!',
                    'home'
                );
                this.updateDeliveryLoading.set(false);
            },
            error: (error: HttpErrorResponse) => {
                this.updateDeliveryLoading.set(false);
                this.notificationService.showError(error.error, 'home');
            },
        });
    }
}
