import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, signal } from '@angular/core';
import { BehaviorSubject, Subject } from 'rxjs';

import { ApiService } from '../_services/api.service';
import { AuxiliaryAccount } from '../core/interfaces/accounts.interface';
import { NotificationsService } from '../_services/notifications.service';

@Injectable({
    providedIn: 'root',
})
export class AuxiliaryService {
    private host = this.api.host;
    accounts = new BehaviorSubject<AuxiliaryAccount[]>([]);

    customers = new BehaviorSubject<AuxiliaryAccount[]>([]);
    suppliers = new BehaviorSubject<AuxiliaryAccount[]>([]);
    banks = new BehaviorSubject<AuxiliaryAccount[]>([]);
    employees = new BehaviorSubject<AuxiliaryAccount[]>([]);

    dialogVisible = new BehaviorSubject<boolean>(false);
    selectedAccount = new BehaviorSubject(null);

    constructor(
        private http: HttpClient,
        private api: ApiService,
        private notificationService: NotificationsService
    ) {
        this.getAccounts();
        this.getCustomers();
        this.getSuppliers();
        this.getEmployees();
        this.getBanks();
    }

    // get accounts
    getAccounts() {
        this.http
            .get<AuxiliaryAccount[]>(`${this.host}/auxiliary/all`)
            .subscribe({
                next: (res) => {
                    this.accounts.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    customersLoading = signal(false)
    // get customers
    getCustomers() {
        this.customersLoading.set(true)
        this.http
            .get<AuxiliaryAccount[]>(`${this.host}/auxiliary/customers`)
            .subscribe({
                next: (res) => {
                    this.customers.next(res);
                    this.customersLoading.set(false)
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                    this.customersLoading.set(false)
                },
            });
    }

    // get suppliers
    getSuppliers() {
        this.http
            .get<AuxiliaryAccount[]>(`${this.host}/auxiliary/suppliers`)
            .subscribe({
                next: (res) => {
                    this.suppliers.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // get banks
    getBanks() {
        this.http
            .get<AuxiliaryAccount[]>(`${this.host}/auxiliary/banks`)
            .subscribe({
                next: (res) => {
                    this.banks.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // get employees
    getEmployees() {
        this.http
            .get<AuxiliaryAccount[]>(`${this.host}/auxiliary/employees`)
            .subscribe({
                next: (res) => {
                    this.employees.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // add account
    addAccount(account) {
        this.http
            .post<AuxiliaryAccount>(`${this.host}/auxiliary`, account)
            .subscribe({
                next: (res) => {
                    this.notificationService.showSuccess(
                        'Account added successfully!',
                        'home'
                    );
                    this.accounts.next([...this.accounts.value, res]);
                    this.dialogVisible.next(false);
                    this.getCustomers();
                    this.getSuppliers();
                    this.getEmployees();
                    this.getBanks();
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // edit account
    editAccount(account) {
        this.http
            .put<AuxiliaryAccount>(`${this.host}/auxiliary`, account)
            .subscribe({
                next: (res) => {
                    this.selectedAccount.next(res);
                    this.notificationService.showSuccess(
                        'Account updated successfully!',
                        'home'
                    );
                    let index = this.accounts.value.findIndex(
                        (x) => x.account_id == res.account_id
                    );
                    let temp = this.accounts.value;
                    temp[index] = res;
                    this.accounts.next(temp);

                    this.dialogVisible.next(false);
                    this.getCustomers();
                    this.getSuppliers();
                    this.getEmployees();
                    this.getBanks();
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }

    // delete account
    deleteAccount(account: AuxiliaryAccount) {
        this.http
            .delete<any>(`${this.host}/auxiliary/${account.account_id}`)
            .subscribe({
                next: (res) => {
                    this.getAccounts();
                    this.getCustomers();
                    this.getSuppliers();
                    this.getEmployees();
                    this.getBanks();
                    this.notificationService.showSuccess(res.message, 'home');
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }
}
