import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
    name: 'lira',
    standalone: true
})
export class LiraPipe implements PipeTransform {

    transform(value: number,
    ): string | null {
        return new Intl.NumberFormat('en-US', {
            minimumFractionDigits: 0,
        }).format(Number(value)) + ` L.L`;
    }

}
